from typing import Callable, Optional, Any, List
from playwright.sync_api import Page, Locator, expect
import allure
import time
from src.core.logger import get_logger

logger = get_logger(__name__)

class CustomAssertions:
    """Custom assertion methods for robust testing"""

    @staticmethod
    def assert_with_retry(
        assertion_func: Callable,
        timeout: int = 30,
        interval: float = 0.5,
        message: Optional[str] = None
    ) -> bool:
        """
        Retry assertion until it passes or timeout

        Args:
            assertion_func: Function that raises AssertionError on failure
            timeout: Maximum time to wait in seconds
            interval: Time between retries in seconds
            message: Custom error message

        Returns:
            bool: True if assertion passed
        """
        end_time = time.time() + timeout
        last_error = None

        while time.time() < end_time:
            try:
                assertion_func()
                return True
            except AssertionError as e:
                last_error = e
                time.sleep(interval)
            except Exception as e:
                last_error = AssertionError(f"Unexpected error: {e}")
                time.sleep(interval)

        if message:
            raise AssertionError(f"{message}\nLast error: {last_error}")
        else:
            raise last_error if last_error else AssertionError("Assertion failed")

    @staticmethod
    def assert_element_has_class(
        page: Page,
        selector: str,
        expected_class: str,
        timeout: int = 10
    ):
        """Assert element has specific CSS class"""
        with allure.step(f"Verify element {selector} has class '{expected_class}'"):
            element = page.locator(selector).first
            expect(element).to_have_class(f".*{expected_class}.*", timeout=timeout * 1000)

    @staticmethod
    def assert_element_count(
        page: Page,
        selector: str,
        expected_count: int,
        timeout: int = 10
    ):
        """Assert exact count of elements"""
        with allure.step(f"Verify {expected_count} elements found for {selector}"):

            def check_count():
                actual_count = page.locator(selector).count()
                assert actual_count == expected_count, \
                    f"Expected {expected_count} elements, found {actual_count}"

            CustomAssertions.assert_with_retry(check_count, timeout=timeout)

    @staticmethod
    def assert_url_matches_pattern(
        page: Page,
        pattern: str,
        timeout: int = 10
    ):
        """Assert URL matches regex pattern"""
        with allure.step(f"Verify URL matches pattern: {pattern}"):
            expect(page).to_have_url(f".*{pattern}.*", timeout=timeout * 1000)

    @staticmethod
    def assert_page_title(
        page: Page,
        expected_title: str,
        timeout: int = 10
    ):
        """Assert page title"""
        with allure.step(f"Verify page title is '{expected_title}'"):
            expect(page).to_have_title(expected_title, timeout=timeout * 1000)

    @staticmethod
    def assert_element_attribute(
        element: Locator,
        attribute: str,
        expected_value: str,
        timeout: int = 10
    ):
        """Assert element attribute value"""
        with allure.step(f"Verify element attribute {attribute} = '{expected_value}'"):
            expect(element).to_have_attribute(attribute, expected_value, timeout=timeout * 1000)

    @staticmethod
    def assert_soft(assertions: List[Callable], fail_fast: bool = False):
        """
        Perform multiple assertions with soft failure option

        Args:
            assertions: List of assertion functions
            fail_fast: If True, stop on first failure
        """
        errors = []

        for i, assertion_func in enumerate(assertions):
            try:
                assertion_func()
            except AssertionError as e:
                errors.append(f"Assertion {i + 1} failed: {e}")
                if fail_fast:
                    break

        if errors:
            error_message = "\n".join(errors)
            allure.attach(error_message, name="Soft Assertion Errors")
            raise AssertionError(f"Soft assertions failed:\n{error_message}")

    @staticmethod
    def assert_performance_metric(
        page: Page,
        metric_name: str,
        max_value: float,
        description: Optional[str] = None
    ):
        """Assert performance metric is within acceptable range"""
        with allure.step(f"Verify {metric_name} <= {max_value}ms"):
            metrics = page.evaluate("""
                () => {
                    const [timing] = performance.getEntriesByType('navigation');
                    return {
                        'dns_lookup': timing.domainLookupEnd - timing.domainLookupStart,
                        'tcp_connection': timing.connectEnd - timing.connectStart,
                        'request_response': timing.responseEnd - timing.requestStart,
                        'dom_loading': timing.domContentLoadedEventEnd - timing.domContentLoadedEventStart,
                        'page_load': timing.loadEventEnd - timing.loadEventStart,
                        'total_time': timing.loadEventEnd - timing.navigationStart
                    };
                }
            """)

            actual_value = metrics.get(metric_name, 0)
            assert actual_value <= max_value, \
                f"{metric_name} exceeded limit: {actual_value}ms > {max_value}ms"

            if description:
                allure.attach(f"{metric_name}: {actual_value}ms", name=description)

class WaitHandlers:
    """Custom wait handlers for dynamic content"""

    @staticmethod
    def wait_for_ajax_complete(page: Page, timeout: int = 30):
        """Wait for all AJAX requests to complete"""
        def is_ajax_complete():
            return page.evaluate("""() => {
                return window.jQuery ? jQuery.active === 0 : true;
            }""")

        end_time = time.time() + timeout
        while time.time() < end_time:
            if is_ajax_complete():
                return True
            time.sleep(0.5)

        raise TimeoutError(f"AJAX requests did not complete within {timeout} seconds")

    @staticmethod
    def wait_for_angular_ready(page: Page, timeout: int = 30):
        """Wait for Angular applications to be ready"""
        def is_angular_ready():
            return page.evaluate("""() => {
                if (window.angular) {
                    const injector = window.angular.element(document).injector();
                    return injector.get('$http').pendingRequests.length === 0;
                }
                return true;
            }""")

        end_time = time.time() + timeout
        while time.time() < end_time:
            if is_angular_ready():
                return True
            time.sleep(0.5)

        raise TimeoutError(f"Angular did not become ready within {timeout} seconds")

    @staticmethod
    def wait_for_react_ready(page: Page, timeout: int = 30):
        """Wait for React applications to be ready"""
        def is_react_ready():
            return page.evaluate("""() => {
                // Check for React loading state
                const reactRoot = document.querySelector('[data-reactroot], [data-reactid]');
                if (reactRoot) {
                    // Check if React has finished rendering
                    return !reactRoot.hasAttribute('data-react-loading');
                }
                return true;
            }""")

        end_time = time.time() + timeout
        while time.time() < end_time:
            if is_react_ready():
                return True
            time.sleep(0.5)

        raise TimeoutError(f"React did not become ready within {timeout} seconds")

    @staticmethod
    def wait_for_element_stable(
        page: Page,
        selector: str,
        stability_time: float = 1.0,
        timeout: int = 30
    ):
        """
        Wait for element to be stable (not moving/changing)

        Args:
            page: Playwright page object
            selector: Element selector
            stability_time: Time element must be stable (seconds)
            timeout: Maximum wait time (seconds)
        """
        element = page.locator(selector).first
        start_time = time.time()
        stable_start = None

        while time.time() - start_time < timeout:
            try:
                # Get current bounding box
                current_box = element.bounding_box()

                if current_box:
                    if stable_start is None:
                        stable_start = time.time()
                    elif time.time() - stable_start >= stability_time:
                        return True
                else:
                    stable_start = None

                time.sleep(0.1)

            except Exception:
                stable_start = None
                time.sleep(0.1)

        raise TimeoutError(f"Element {selector} did not stabilize within {timeout} seconds")

    @staticmethod
    def wait_for_animation_complete(page: Page, selector: str, timeout: int = 10):
        """Wait for CSS animations to complete"""
        def is_animation_complete():
            return page.evaluate(f"""(selector) => {
                const element = document.querySelector(selector);
                if (!element) return true;

                const style = window.getComputedStyle(element);
                const animation = style.animationName || style.webkitAnimationName;
                const transition = style.transitionProperty || style.webkitTransitionProperty;

                return animation === 'none' && transition === 'none';
            }""", selector)

        end_time = time.time() + timeout
        while time.time() < end_time:
            if is_animation_complete():
                return True
            time.sleep(0.1)

        raise TimeoutError(f"Animations for {selector} did not complete within {timeout} seconds")

    @staticmethod
    def wait_for_images_to_load(page: Page, timeout: int = 30):
        """Wait for all images to load"""
        def all_images_loaded():
            return page.evaluate("""() => {
                const images = document.getElementsByTagName('img');
                for (let img of images) {
                    if (!img.complete) return false;
                    if (img.naturalWidth === 0) return false;
                }
                return true;
            }""")

        end_time = time.time() + timeout
        while time.time() < end_time:
            if all_images_loaded():
                return True
            time.sleep(0.5)

        raise TimeoutError(f"Images did not load within {timeout} seconds")

