import requests
from typing import Dict, Optional, Any, Union, List, Tuple
from dataclasses import dataclass
from pydantic import BaseModel, ValidationError
import jsonschema
import json
import time
from datetime import datetime
from src.core.logger import get_logger
from src.config.base_config import get_config

logger = get_logger(__name__)

@dataclass
class APIResponse:
    """Standard API response container with enhanced metadata"""
    status_code: int
    headers: Dict[str, str]
    body: Any
    elapsed_time: float
    request: Optional[Dict] = None
    cookies: Optional[Dict] = None
    encoding: Optional[str] = None
    content_type: Optional[str] = None

    def __post_init__(self):
        # Parse JSON body if content type indicates JSON
        if isinstance(self.body, (str, bytes)) and \
           self.content_type and 'application/json' in self.content_type:
            try:
                self.body = json.loads(self.body)
            except json.JSONDecodeError:
                pass  # Keep as string if not valid JSON

class APIClient:
    """REST API client with built-in validation, retry logic, and performance tracking"""

    def __init__(self, base_url: Optional[str] = None):
        self.config = get_config()
        self.base_url = base_url or self.config.api_base_url
        self.session = requests.Session()
        self._setup_session()
        self.request_history: List[Dict] = []
        self.max_history_size = 100

    def _setup_session(self):
        """Setup session with default headers, auth, and retry strategy"""
        # Default headers
        self.session.headers.update({
            "Content-Type": "application/json",
            "Accept": "application/json",
            "User-Agent": "ShopSmart-APITest/1.0",
            "X-Request-ID": f"test-{datetime.now().strftime('%Y%m%d%H%M%S')}"
        })

        # Add authentication if configured
        if hasattr(self.config, 'api_token') and self.config.api_token:
            self.session.headers["Authorization"] = f"Bearer {self.config.api_token}"

        # Setup retry adapter with exponential backoff
        from requests.adapters import HTTPAdapter
        from urllib3.util.retry import Retry

        retry_strategy = Retry(
            total=self.config.api_retry_attempts,
            backoff_factor=self.config.api_retry_delay,
            status_forcelist=[429, 500, 502, 503, 504],
            allowed_methods=["GET", "POST", "PUT", "DELETE", "PATCH"],
            raise_on_status=False
        )

        adapter = HTTPAdapter(
            max_retries=retry_strategy,
            pool_connections=10,
            pool_maxsize=10,
            pool_block=True
        )

        self.session.mount("http://", adapter)
        self.session.mount("https://", adapter)

        logger.info("API client session configured")

    def _make_request(
        self,
        method: str,
        endpoint: str,
        **kwargs
    ) -> APIResponse:
        """Make HTTP request with comprehensive logging and error handling"""
        url = f"{self.base_url}{endpoint}"

        # Prepare request data for logging
        request_data = {
            "method": method,
            "url": url,
            "headers": dict(self.session.headers),
            "timestamp": datetime.now().isoformat(),
            **kwargs
        }

        if "json" in kwargs:
            request_data["json"] = kwargs["json"]
        if "data" in kwargs:
            request_data["data"] = kwargs["data"]
        if "params" in kwargs:
            request_data["params"] = kwargs["params"]
        if "files" in kwargs:
            request_data["files"] = "[FILE_DATA]"  # Don't log actual file data

        logger.info(f"Making {method} request to {url}")

        try:
            start_time = time.time()
            response = self.session.request(method, url, **kwargs)
            elapsed_time = time.time() - start_time

            # Log response details
            logger.debug(f"Response status: {response.status_code}")
            logger.debug(f"Response time: {elapsed_time:.2f}s")

            # Parse response body
            content_type = response.headers.get('Content-Type', '')

            try:
                if 'application/json' in content_type:
                    body = response.json()
                else:
                    body = response.text
            except ValueError:
                body = response.content

            # Create API response object
            api_response = APIResponse(
                status_code=response.status_code,
                headers=dict(response.headers),
                body=body,
                elapsed_time=elapsed_time,
                request=request_data,
                cookies=dict(response.cookies),
                encoding=response.encoding,
                content_type=content_type
            )

            # Add to history
            self.request_history.append({
                "request": request_data,
                "response": {
                    "status_code": response.status_code,
                    "elapsed_time": elapsed_time,
                    "headers": dict(response.headers)
                }
            })

            # Keep history size manageable
            if len(self.request_history) > self.max_history_size:
                self.request_history = self.request_history[-self.max_history_size:]

            # Log error responses
            if response.status_code >= 400:
                logger.warning(
                    f"API error {response.status_code} for {method} {url}: {body}"
                )

            return api_response

        except requests.exceptions.RequestException as e:
            logger.error(f"Request failed: {e}")
            raise APIError(f"Request failed: {str(e)}")
        except Exception as e:
            logger.error(f"Unexpected error during request: {e}")
            raise

    # CRUD operations
    def get(self, endpoint: str, **kwargs) -> APIResponse:
        """GET request"""
        return self._make_request("GET", endpoint, **kwargs)

    def post(self, endpoint: str, **kwargs) -> APIResponse:
        """POST request"""
        return self._make_request("POST", endpoint, **kwargs)

    def put(self, endpoint: str, **kwargs) -> APIResponse:
        """PUT request"""
        return self._make_request("PUT", endpoint, **kwargs)

    def patch(self, endpoint: str, **kwargs) -> APIResponse:
        """PATCH request"""
        return self._make_request("PATCH", endpoint, **kwargs)

    def delete(self, endpoint: str, **kwargs) -> APIResponse:
        """DELETE request"""
        return self._make_request("DELETE", endpoint, **kwargs)

    def head(self, endpoint: str, **kwargs) -> APIResponse:
        """HEAD request"""
        return self._make_request("HEAD", endpoint, **kwargs)

    def options(self, endpoint: str, **kwargs) -> APIResponse:
        """OPTIONS request"""
        return self._make_request("OPTIONS", endpoint, **kwargs)

    # Authentication methods
    def login(self, username: str, password: str) -> str:
        """Authenticate and get token"""
        endpoint = "/auth/login"
        payload = {
            "username": username,
            "password": password
        }

        response = self.post(endpoint, json=payload)

        if response.status_code == 200:
            token = response.body.get("token")
            if token:
                self.session.headers["Authorization"] = f"Bearer {token}"
                logger.info("Authentication successful")
                return token

        raise AuthenticationError(f"Login failed: {response.body}")

    def logout(self):
        """Clear authentication"""
        if "Authorization" in self.session.headers:
            response = self.post("/auth/logout")
            if response.status_code == 200:
                del self.session.headers["Authorization"]
                logger.info("Logged out successfully")

    def refresh_token(self, refresh_token: str) -> Dict[str, str]:
        """Refresh access token"""
        payload = {"refresh_token": refresh_token}
        response = self.post("/auth/refresh", json=payload)

        if response.status_code == 200:
            return response.body

        raise AuthenticationError(f"Token refresh failed: {response.body}")

    # Validation methods
    def validate_response_schema(self, response: APIResponse, schema: Dict) -> bool:
        """Validate response against JSON schema"""
        try:
            jsonschema.validate(instance=response.body, schema=schema)
            logger.debug("Schema validation passed")
            return True
        except jsonschema.ValidationError as e:
            logger.error(f"Schema validation failed: {e}")
            raise ValidationError(f"Schema validation failed: {e}")

    def validate_response_model(self, response: APIResponse, model: BaseModel) -> BaseModel:
        """Validate response against Pydantic model"""
        try:
            validated_model = model(**response.body)
            logger.debug(f"Model validation passed for {model.__name__}")
            return validated_model
        except ValidationError as e:
            logger.error(f"Model validation failed: {e}")
            raise ValidationError(f"Model validation failed: {e}")

    def validate_status_code(self, response: APIResponse, expected_code: int) -> bool:
        """Validate response status code"""
        if response.status_code != expected_code:
            raise AssertionError(
                f"Expected status code {expected_code}, got {response.status_code}"
            )
        return True

    # Performance monitoring
    def assert_response_time(self, response: APIResponse, max_time: float) -> bool:
        """Assert response time is within limit"""
        assert response.elapsed_time <= max_time, \
            f"Response time {response.elapsed_time:.2f}s exceeds limit {max_time}s"
        return True

    def get_performance_metrics(self) -> Dict[str, Any]:
        """Get performance metrics from request history"""
        if not self.request_history:
            return {}

        response_times = [r["response"]["elapsed_time"] for r in self.request_history]
        status_codes = [r["response"]["status_code"] for r in self.request_history]

        return {
            "total_requests": len(self.request_history),
            "avg_response_time": sum(response_times) / len(response_times),
            "min_response_time": min(response_times),
            "max_response_time": max(response_times),
            "success_rate": sum(1 for code in status_codes if code < 400) / len(status_codes) * 100,
            "status_code_distribution": {
                code: status_codes.count(code) for code in set(status_codes)
            }
        }

    # File operations
    def upload_file(self, endpoint: str, file_path: str, 
                   field_name: str = "file", extra_data: Optional[Dict] = None) -> APIResponse:
        """Upload a file with multipart form data"""
        with open(file_path, 'rb') as file:
            files = {field_name: file}
            data = extra_data or {}
            return self.post(endpoint, files=files, data=data)

    def download_file(self, endpoint: str, save_path: str) -> bool:
        """Download a file"""
        response = self.get(endpoint, stream=True)

        if response.status_code == 200:
            with open(save_path, 'wb') as file:
                for chunk in response.iter_content(chunk_size=8192):
                    if chunk:
                        file.write(chunk)
            logger.info(f"File downloaded to {save_path}")
            return True

        logger.error(f"File download failed with status {response.status_code}")
        return False

    # Rate limiting and retry handling
    def handle_rate_limit(self, response: APIResponse) -> bool:
        """Handle rate limiting with exponential backoff"""
        if response.status_code == 429:
            retry_after = response.headers.get('Retry-After')
            wait_time = int(retry_after) if retry_after else 5

            logger.warning(f"Rate limited. Waiting {wait_time} seconds...")
            time.sleep(wait_time)
            return True

        return False

    def wait_for_condition(self, condition_func: Callable[[], bool], 
                          timeout: int = 30, interval: float = 1) -> bool:
        """Wait for condition to be true (useful for async operations)"""
        end_time = time.time() + timeout

        while time.time() < end_time:
            if condition_func():
                return True
            time.sleep(interval)

        raise TimeoutError(f"Condition not met within {timeout} seconds")

    # Batch operations
    def batch_requests(self, requests: List[Tuple[str, str, Dict]]) -> List[APIResponse]:
        """Execute multiple requests in sequence"""
        responses = []

        for method, endpoint, kwargs in requests:
            response = self._make_request(method, endpoint, **kwargs)
            responses.append(response)

            # Handle rate limiting
            if self.handle_rate_limit(response):
                # Retry the same request after rate limit wait
                response = self._make_request(method, endpoint, **kwargs)
                responses[-1] = response

        return responses

# Custom exceptions
class APIError(Exception):
    """Base API exception"""
    pass

class AuthenticationError(APIError):
    """Authentication failed"""
    pass

class ValidationError(APIError):
    """Response validation failed"""
    pass

class RateLimitError(APIError):
    """Rate limit exceeded"""
    pass

class TimeoutError(APIError):
    """Operation timeout"""
    pass

