import json
from typing import Dict, List, Any, Optional
import asyncio
from src.core.logger import get_logger

logger = get_logger(__name__)

class AccessibilityTester:
    """Accessibility testing using axe-core"""

    def __init__(self, page):
        self.page = page
        self.results = None

    async def run_accessibility_scan(self, context: Optional[str] = None) -> Dict[str, Any]:
        """Run accessibility scan using axe-core"""
        # Inject axe-core script
        axe_script = """
        const script = document.createElement('script');
        script.src = 'https://cdnjs.cloudflare.com/ajax/libs/axe-core/4.6.0/axe.min.js';
        document.head.appendChild(script);
        """

        await self.page.evaluate(axe_script)

        # Wait for axe to load
        await self.page.wait_for_function('typeof axe !== "undefined"')

        # Run accessibility scan
        scan_options = {}
        if context:
            scan_options["context"] = context

        results = await self.page.evaluate(
            """async (options) => {
                return await axe.run(document, options);
            }""",
            scan_options
        )

        self.results = results
        return results

    def analyze_results(self, results: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Analyze and categorize accessibility results"""
        results = results or self.results
        if not results:
            return {}

        analysis = {
            "violations": [],
            "passes": [],
            "incomplete": [],
            "inapplicable": [],
            "summary": {
                "total_violations": len(results.get("violations", [])),
                "critical_violations": 0,
                "serious_violations": 0,
                "moderate_violations": 0,
                "minor_violations": 0,
                "impact_levels": {},
                "wcag_levels": {}
            }
        }

        # Analyze violations
        for violation in results.get("violations", []):
            # Categorize by impact
            impact = violation.get("impact", "minor")
            analysis["summary"]["impact_levels"][impact] = \
                analysis["summary"]["impact_levels"].get(impact, 0) + 1

            # Count by severity
            if impact == "critical":
                analysis["summary"]["critical_violations"] += 1
            elif impact == "serious":
                analysis["summary"]["serious_violations"] += 1
            elif impact == "moderate":
                analysis["summary"]["moderate_violations"] += 1
            else:
                analysis["summary"]["minor_violations"] += 1

            # Categorize by WCAG level
            for tag in violation.get("tags", []):
                if tag.startswith("wcag"):
                    analysis["summary"]["wcag_levels"][tag] = \
                        analysis["summary"]["wcag_levels"].get(tag, 0) + 1

            violation_data = {
                "id": violation.get("id"),
                "description": violation.get("description"),
                "help": violation.get("help"),
                "helpUrl": violation.get("helpUrl"),
                "impact": impact,
                "nodes": len(violation.get("nodes", [])),
                "tags": violation.get("tags", [])
            }

            analysis["violations"].append(violation_data)

        return analysis

    def check_compliance_level(self, analysis: Dict[str, Any], 
                             level: str = "AA") -> Dict[str, Any]:
        """Check compliance with specific WCAG level"""
        wcag_levels = {
            "A": ["wcag2a", "wcag2aa", "wcag2aaa", "wcag21a", "wcag21aa", "wcag21aaa"],
            "AA": ["wcag2aa", "wcag2aaa", "wcag21aa", "wcag21aaa"],
            "AAA": ["wcag2aaa", "wcag21aaa"]
        }

        target_levels = wcag_levels.get(level.upper(), [])

        compliance = {
            "level": level,
            "passed": True,
            "violations": [],
            "details": {}
        }

        for violation in analysis.get("violations", []):
            # Check if violation is relevant to target WCAG level
            relevant_tags = [tag for tag in violation["tags"] if tag in target_levels]

            if relevant_tags:
                compliance["passed"] = False
                compliance["violations"].append({
                    "id": violation["id"],
                    "description": violation["description"],
                    "impact": violation["impact"],
                    "wcag_levels": relevant_tags
                })

        return compliance

    def generate_report(self, analysis: Dict[str, Any], 
                       output_format: str = "html") -> str:
        """Generate accessibility test report"""
        report = {
            "timestamp": datetime.now().isoformat(),
            "url": self.page.url,
            "analysis": analysis,
            "recommendations": self._generate_recommendations(analysis),
            "compliance": {
                "A": self.check_compliance_level(analysis, "A"),
                "AA": self.check_compliance_level(analysis, "AA"),
                "AAA": self.check_compliance_level(analysis, "AAA")
            }
        }

        if output_format == "json":
            return json.dumps(report, indent=2)
        elif output_format == "html":
            return self._generate_html_report(report)
        else:
            raise ValueError(f"Unsupported format: {output_format}")

    def _generate_recommendations(self, analysis: Dict[str, Any]) -> List[str]:
        """Generate accessibility recommendations"""
        recommendations = []

        # Group violations by type
        violation_types = {}
        for violation in analysis["violations"]:
            violation_id = violation["id"]
            if violation_id not in violation_types:
                violation_types[violation_id] = {
                    "count": 0,
                    "description": violation["description"],
                    "help": violation["help"],
                    "impact": violation["impact"]
                }
            violation_types[violation_id]["count"] += 1

        # Generate recommendations
        for violation_id, data in violation_types.items():
            recommendations.append(
                f"Fix {violation_id}: {data['description']} "
                f"(Impact: {data['impact']}, Affects: {data['count']} elements)"
            )

        return recommendations

    def _generate_html_report(self, report: Dict[str, Any]) -> str:
        """Generate HTML accessibility report"""
        html_template = """
        <!DOCTYPE html>
        <html lang="en">
        <head>
            <meta charset="UTF-8">
            <meta name="viewport" content="width=device-width, initial-scale=1.0">
            <title>Accessibility Test Report</title>
            <style>
                body { font-family: Arial, sans-serif; margin: 20px; line-height: 1.6; }
                .summary { background: #f5f5f5; padding: 20px; border-radius: 5px; margin-bottom: 20px; }
                .violation { border-left: 4px solid #e74c3c; padding: 15px; margin: 10px 0; background: #fff; }
                .critical { border-left-color: #e74c3c; }
                .serious { border-left-color: #e67e22; }
                .moderate { border-left-color: #f1c40f; }
                .minor { border-left-color: #3498db; }
                .pass { border-left: 4px solid #2ecc71; padding: 10px; margin: 10px 0; background: #fff; }
                .impact-badge { padding: 3px 10px; border-radius: 3px; color: white; font-size: 12px; font-weight: bold; }
                .critical-badge { background: #e74c3c; }
                .serious-badge { background: #e67e22; }
                .moderate-badge { background: #f1c40f; color: #333; }
                .minor-badge { background: #3498db; }
                .compliance-badge { padding: 5px 15px; border-radius: 5px; margin: 5px; }
                .compliance-pass { background: #2ecc71; color: white; }
                .compliance-fail { background: #e74c3c; color: white; }
                table { width: 100%; border-collapse: collapse; margin: 20px 0; }
                th, td { padding: 12px; text-align: left; border-bottom: 1px solid #ddd; }
                th { background: #f5f5f5; font-weight: bold; }
                tr:hover { background: #f9f9f9; }
            </style>
        </head>
        <body>
            <h1>Accessibility Test Report</h1>

            <div class="summary">
                <h2>Summary</h2>
                <p><strong>URL:</strong> {{ report.url }}</p>
                <p><strong>Timestamp:</strong> {{ report.timestamp }}</p>
                <p><strong>Total Violations:</strong> {{ report.analysis.summary.total_violations }}</p>
                <p><strong>Critical:</strong> {{ report.analysis.summary.critical_violations }}</p>
                <p><strong>Serious:</strong> {{ report.analysis.summary.serious_violations }}</p>
                <p><strong>Moderate:</strong> {{ report.analysis.summary.moderate_violations }}</p>
                <p><strong>Minor:</strong> {{ report.analysis.summary.minor_violations }}</p>

                <h3>WCAG Compliance</h3>
                {% for level, compliance in report.compliance.items() %}
                <span class="compliance-badge {{ 'compliance-pass' if compliance.passed else 'compliance-fail' }}">
                    WCAG {{ level }}: {{ 'PASS' if compliance.passed else 'FAIL' }}
                </span>
                {% endfor %}
            </div>

            <h2>Violations</h2>
            {% if report.analysis.violations %}
                {% for violation in report.analysis.violations %}
                <div class="violation {{ violation.impact }}">
                    <span class="impact-badge {{ violation.impact }}-badge">{{ violation.impact|upper }}</span>
                    <h3>{{ violation.id }}: {{ violation.description }}</h3>
                    <p><strong>Help:</strong> {{ violation.help }}</p>
                    <p><strong>Help URL:</strong> <a href="{{ violation.helpUrl }}" target="_blank">{{ violation.helpUrl }}</a></p>
                    <p><strong>Affected Elements:</strong> {{ violation.nodes }}</p>
                    <p><strong>Tags:</strong> {{ violation.tags|join(', ') }}</p>
                </div>
                {% endfor %}
            {% else %}
                <p>No accessibility violations found! 🎉</p>
            {% endif %}

            <h2>Recommendations</h2>
            <ul>
                {% for recommendation in report.recommendations %}
                <li>{{ recommendation }}</li>
                {% endfor %}
            </ul>
        </body>
        </html>
        """

        import jinja2
        template = jinja2.Template(html_template)
        return template.render(report=report)

