# Accessibility test decorator
def accessibility_test(threshold: str = "AA"):
    """Decorator for accessibility tests"""
    def decorator(test_func):
        async def async_wrapper(*args, **kwargs):
            # Get accessibility tester
            tester = kwargs.get('accessibility_tester')

            if not tester:
                # Try to get from test instance
                for arg in args:
                    if hasattr(arg, 'accessibility_tester'):
                        tester = arg.accessibility_tester
                        break

            if not tester:
                raise ValueError("Accessibility tester not found")

            # Run accessibility scan
            results = await tester.run_accessibility_scan()
            analysis = tester.analyze_results(results)

            # Check compliance
            compliance = tester.check_compliance_level(analysis, threshold)

            if not compliance["passed"]:
                # Generate report
                report = tester.generate_report(analysis, "html")

                # Save report
                report_dir = "reports/accessibility"
                os.makedirs(report_dir, exist_ok=True)
                report_file = f"{report_dir}/accessibility_{datetime.now().strftime('%Y%m%d_%H%M%S')}.html"

                with open(report_file, 'w') as f:
                    f.write(report)

                # Attach to Allure
                allure.attach.file(
                    report_file,
                    name=f"accessibility_report_{threshold}",
                    attachment_type=allure.attachment_type.HTML
                )

                raise AssertionError(
                    f"Accessibility test failed ({threshold} compliance).\n"
                    f"Violations found: {len(compliance['violations'])}\n"
                    f"Report saved to: {report_file}"
                )

            # Run the actual test
            return await test_func(*args, **kwargs) if asyncio.iscoroutinefunction(test_func) else test_func(*args, **kwargs)

        return async_wrapper
    return decorator

