import json
import requests
from typing import Dict, List, Any, Optional
from urllib.parse import urljoin
from src.core.logger import get_logger
import time

logger = get_logger(__name__)

class SecurityScanner:
    """Security vulnerability scanner"""

    def __init__(self, base_url: str):
        self.base_url = base_url
        self.session = requests.Session()
        self.vulnerabilities = []

    def scan_owasp_top_10(self) -> Dict[str, Any]:
        """Scan for OWASP Top 10 vulnerabilities"""
        scan_results = {
            "timestamp": time.time(),
            "base_url": self.base_url,
            "vulnerabilities": [],
            "summary": {
                "critical": 0,
                "high": 0,
                "medium": 0,
                "low": 0,
                "info": 0
            }
        }

        # 1. Injection Testing
        injection_vulns = self.test_injection_vulnerabilities()
        scan_results["vulnerabilities"].extend(injection_vulns)

        # 2. Broken Authentication
        auth_vulns = self.test_authentication_vulnerabilities()
        scan_results["vulnerabilities"].extend(auth_vulns)

        # 3. Sensitive Data Exposure
        data_vulns = self.test_sensitive_data_exposure()
        scan_results["vulnerabilities"].extend(data_vulns)

        # 4. XML External Entities (XXE)
        xxe_vulns = self.test_xxe_vulnerabilities()
        scan_results["vulnerabilities"].extend(xxe_vulns)

        # 5. Broken Access Control
        access_vulns = self.test_access_control_vulnerabilities()
        scan_results["vulnerabilities"].extend(access_vulns)

        # 6. Security Misconfiguration
        config_vulns = self.test_security_misconfiguration()
        scan_results["vulnerabilities"].extend(config_vulns)

        # 7. Cross-Site Scripting (XSS)
        xss_vulns = self.test_xss_vulnerabilities()
        scan_results["vulnerabilities"].extend(xss_vulns)

        # 8. Insecure Deserialization
        deserialization_vulns = self.test_deserialization_vulnerabilities()
        scan_results["vulnerabilities"].extend(deserialization_vulns)

        # 9. Using Components with Known Vulnerabilities
        component_vulns = self.test_component_vulnerabilities()
        scan_results["vulnerabilities"].extend(component_vulns)

        # 10. Insufficient Logging & Monitoring
        logging_vulns = self.test_logging_vulnerabilities()
        scan_results["vulnerabilities"].extend(logging_vulns)

        # Update summary
        for vuln in scan_results["vulnerabilities"]:
            severity = vuln.get("severity", "info").lower()
            if severity in scan_results["summary"]:
                scan_results["summary"][severity] += 1

        return scan_results

    def test_injection_vulnerabilities(self) -> List[Dict[str, Any]]:
        """Test for SQL injection, command injection, etc."""
        vulnerabilities = []

        # Test SQL injection
        test_payloads = [
            "' OR '1'='1",
            "'; DROP TABLE users; --",
            "' UNION SELECT NULL, username, password FROM users --",
            "1' AND '1'='1",
            "1' AND SLEEP(5) --"
        ]

        endpoints = [
            "/api/v1/products?search=",
            "/api/v1/users?id=",
            "/api/v1/orders?user_id="
        ]

        for endpoint in endpoints:
            for payload in test_payloads:
                url = urljoin(self.base_url, endpoint + payload)
                try:
                    response = self.session.get(url, timeout=5)

                    # Check for SQL error patterns
                    error_patterns = [
                        "SQL syntax",
                        "mysql_fetch",
                        "ORA-",
                        "PostgreSQL",
                        "SQLite",
                        "unclosed quotation mark"
                    ]

                    for pattern in error_patterns:
                        if pattern.lower() in response.text.lower():
                            vulnerabilities.append({
                                "type": "sql_injection",
                                "endpoint": endpoint,
                                "payload": payload,
                                "severity": "critical",
                                "description": f"SQL injection vulnerability detected at {endpoint}",
                                "evidence": response.text[:200]
                            })
                            break

                    # Check for time-based injection
                    if "SLEEP" in payload.upper() and response.elapsed.total_seconds() > 4:
                        vulnerabilities.append({
                            "type": "time_based_sql_injection",
                            "endpoint": endpoint,
                            "payload": payload,
                            "severity": "critical",
                            "description": f"Time-based SQL injection detected at {endpoint}",
                            "evidence": f"Response time: {response.elapsed.total_seconds()} seconds"
                        })

                except Exception as e:
                    logger.warning(f"Error testing SQL injection at {url}: {e}")

        return vulnerabilities

    def test_authentication_vulnerabilities(self) -> List[Dict[str, Any]]:
        """Test for authentication bypass, weak passwords, etc."""
        vulnerabilities = []

        # Test for default credentials
        default_credentials = [
            ("admin", "admin"),
            ("admin", "password"),
            ("root", "root"),
            ("test", "test"),
            ("user", "user")
        ]

        login_url = urljoin(self.base_url, "/api/v1/auth/login")

        for username, password in default_credentials:
            try:
                response = self.session.post(login_url, json={
                    "username": username,
                    "password": password
                }, timeout=5)

                if response.status_code == 200:
                    vulnerabilities.append({
                        "type": "default_credentials",
                        "username": username,
                        "password": password,
                        "severity": "critical",
                        "description": "Default credentials are accepted",
                        "evidence": "Login successful with default credentials"
                    })

            except Exception as e:
                logger.warning(f"Error testing authentication: {e}")

        # Test for user enumeration
        test_usernames = ["admin", "administrator", "test", "user", "demo"]

        for username in test_usernames:
            try:
                response = self.session.post(login_url, json={
                    "username": username,
                    "password": "wrongpassword123"
                }, timeout=5)

                # Check for different error messages
                if "invalid username" in response.text.lower() or \
                   "user not found" in response.text.lower():
                    vulnerabilities.append({
                        "type": "user_enumeration",
                        "username": username,
                        "severity": "medium",
                        "description": "Username enumeration possible via error messages",
                        "evidence": response.text[:200]
                    })

            except Exception as e:
                logger.warning(f"Error testing user enumeration: {e}")

        # Check for missing rate limiting
        for _ in range(10):
            response = self.session.post(login_url, json={
                "username": "test",
                "password": "wrong"
            }, timeout=5)

        if response.status_code != 429:
            vulnerabilities.append({
                "type": "missing_rate_limiting",
                "severity": "medium",
                "description": "No rate limiting on login endpoint",
                "evidence": "10 consecutive failed logins didn't trigger rate limiting"
            })

        return vulnerabilities

    def test_sensitive_data_exposure(self) -> List[Dict[str, Any]]:
        """Test for exposure of sensitive data"""
        vulnerabilities = []

        # Check for sensitive information in responses
        endpoints = [
            "/api/v1/users",
            "/api/v1/orders",
            "/api/v1/profile"
        ]

        sensitive_patterns = [
            "password",
            "credit_card",
            "ssn",
            "social_security",
            "token",
            "secret",
            "api_key",
            "private_key"
        ]

        for endpoint in endpoints:
            try:
                url = urljoin(self.base_url, endpoint)
                response = self.session.get(url, timeout=5)

                if response.status_code == 200:
                    response_text = response.text.lower()

                    for pattern in sensitive_patterns:
                        if pattern in response_text:
                            vulnerabilities.append({
                                "type": "sensitive_data_exposure",
                                "endpoint": endpoint,
                                "pattern": pattern,
                                "severity": "high",
                                "description": f"Sensitive data pattern '{pattern}' found in response",
                                "evidence": f"Pattern found in {endpoint} response"
                            })

            except Exception as e:
                logger.warning(f"Error testing sensitive data exposure at {endpoint}: {e}")

        # Check for missing HTTPS
        if self.base_url.startswith("http://"):
            vulnerabilities.append({
                "type": "missing_https",
                "severity": "high",
                "description": "Application is not using HTTPS",
                "evidence": f"Base URL uses HTTP: {self.base_url}"
            })

        return vulnerabilities

    def test_xss_vulnerabilities(self) -> List[Dict[str, Any]]:
        """Test for Cross-Site Scripting vulnerabilities"""
        vulnerabilities = []

        # XSS test payloads
        xss_payloads = [
            "<script>alert('XSS')</script>",
            "<img src=x onerror=alert('XSS')>",
            "<svg onload=alert('XSS')>",
            "'><script>alert('XSS')</script>",
            "\"><script>alert('XSS')</script>"
        ]

        # Test endpoints that accept user input
        test_endpoints = [
            {"url": "/api/v1/products?search=", "method": "GET"},
            {"url": "/api/v1/comments", "method": "POST"},
            {"url": "/api/v1/contact", "method": "POST"}
        ]

        for endpoint in test_endpoints:
            for payload in xss_payloads:
                try:
                    if endpoint["method"] == "GET":
                        url = urljoin(self.base_url, endpoint["url"] + payload)
                        response = self.session.get(url, timeout=5)
                    else:
                        url = urljoin(self.base_url, endpoint["url"])
                        response = self.session.post(url, json={"content": payload}, timeout=5)

                    # Check if payload is reflected in response
                    if payload in response.text:
                        vulnerabilities.append({
                            "type": "reflected_xss",
                            "endpoint": endpoint["url"],
                            "payload": payload,
                            "severity": "high",
                            "description": f"Reflected XSS vulnerability at {endpoint['url']}",
                            "evidence": f"Payload reflected in response"
                        })

                except Exception as e:
                    logger.warning(f"Error testing XSS at {endpoint['url']}: {e}")

        return vulnerabilities

    def generate_security_report(self, scan_results: Dict[str, Any]) -> str:
        """Generate security scan report"""
        report = {
            "scan_results": scan_results,
            "risk_assessment": self._assess_risk(scan_results),
            "recommendations": self._generate_security_recommendations(scan_results),
            "compliance": self._check_compliance(scan_results)
        }

        # Save report
        report_dir = "reports/security"
        os.makedirs(report_dir, exist_ok=True)

        timestamp = time.strftime("%Y%m%d_%H%M%S")
        report_file = f"{report_dir}/security_scan_{timestamp}.json"

        with open(report_file, 'w') as f:
            json.dump(report, f, indent=2)

        # Generate HTML report
        html_report = self._generate_html_report(report)
        html_file = f"{report_dir}/security_scan_{timestamp}.html"

        with open(html_file, 'w') as f:
            f.write(html_report)

        logger.info(f"Security scan completed. Report saved to: {report_file}")
        return report_file

    def _assess_risk(self, scan_results: Dict[str, Any]) -> Dict[str, Any]:
        """Assess overall security risk"""
        summary = scan_results["summary"]

        risk_score = (
            summary["critical"] * 10 +
            summary["high"] * 5 +
            summary["medium"] * 3 +
            summary["low"] * 1 +
            summary["info"] * 0.1
        )

        if risk_score >= 20:
            risk_level = "CRITICAL"
        elif risk_score >= 10:
            risk_level = "HIGH"
        elif risk_score >= 5:
            risk_level = "MEDIUM"
        elif risk_score >= 1:
            risk_level = "LOW"
        else:
            risk_level = "INFO"

        return {
            "risk_score": risk_score,
            "risk_level": risk_level,
            "assessment": self._get_risk_assessment_text(risk_level)
        }

    def _get_risk_assessment_text(self, risk_level: str) -> str:
        """Get risk assessment text"""
        assessments = {
            "CRITICAL": "Immediate action required. Critical vulnerabilities present that could lead to complete system compromise.",
            "HIGH": "Urgent attention needed. High-risk vulnerabilities present that could lead to significant data breaches.",
            "MEDIUM": "Address in next development cycle. Medium-risk vulnerabilities present that should be fixed.",
            "LOW": "Monitor and address as part of regular maintenance. Low-risk vulnerabilities present.",
            "INFO": "No significant security risks detected. Informational findings only."
        }

        return assessments.get(risk_level, "Risk assessment not available.")

    def _generate_security_recommendations(self, scan_results: Dict[str, Any]) -> List[str]:
        """Generate security recommendations"""
        recommendations = []

        # General recommendations based on findings
        if scan_results["summary"]["critical"] > 0:
            recommendations.append(
                "Address critical vulnerabilities immediately before deployment."
            )

        if scan_results["summary"]["high"] > 0:
            recommendations.append(
                "Schedule fixes for high-risk vulnerabilities in the next sprint."
            )

        # Specific recommendations
        for vuln in scan_results["vulnerabilities"]:
            if vuln["type"] == "sql_injection":
                recommendations.append(
                    f"Implement parameterized queries or ORM for {vuln['endpoint']}"
                )
            elif vuln["type"] == "missing_https":
                recommendations.append("Implement HTTPS with proper SSL/TLS configuration")
            elif vuln["type"] == "default_credentials":
                recommendations.append("Change default credentials and implement strong password policies")
            elif vuln["type"] == "missing_rate_limiting":
                recommendations.append("Implement rate limiting on authentication endpoints")
            elif vuln["type"] == "xss":
                recommendations.append("Implement proper input sanitization and output encoding")

        return list(set(recommendations))[:10]  # Limit to top 10 unique recommendations

    def _check_compliance(self, scan_results: Dict[str, Any]) -> Dict[str, bool]:
        """Check security compliance standards"""
        compliance = {
            "owasp_top_10": scan_results["summary"]["critical"] == 0 and scan_results["summary"]["high"] == 0,
            "pci_dss": scan_results["summary"]["critical"] == 0,
            "gdpr": scan_results["summary"]["critical"] == 0 and scan_results["summary"]["high"] == 0,
            "hipaa": scan_results["summary"]["critical"] == 0
        }

        return compliance

