public class RobustElementFinder {

    private static final int MAX_RETRIES = 3;
    private static final int TIMEOUT_SECONDS = 30;
    private static final int POLL_INTERVAL_MS = 500;

    public WebElement findElementWithRetry(WebDriver driver, By locator, String expectedText) {
        int attempts = 0;
        while (attempts < MAX_RETRIES) {
            try {
                WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(TIMEOUT_SECONDS));
                wait.pollingEvery(Duration.ofMillis(POLL_INTERVAL_MS));
                wait.ignoring(StaleElementReferenceException.class);
                wait.ignoring(NoSuchElementException.class);

                // Wait for element and text
                return wait.until(driver -> {
                    List<WebElement> elements = driver.findElements(locator);
                    for (WebElement element : elements) {
                        try {
                            if (element.isDisplayed() && element.isEnabled() && 
                                element.getText().contains(expectedText)) {
                                return element;
                            }
                        } catch (StaleElementReferenceException e) {
                            continue;
                        }
                    }
                    return null;
                });

            } catch (TimeoutException e) {
                attempts++;
                logger.warn("Attempt " + attempts + " failed for locator: " + locator);
                if (attempts == MAX_RETRIES) {
                    takeScreenshot(driver, "element_not_found_" + locator);
                    throw e;
                }
                // Wait before retry
                try { Thread.sleep(1000); } catch (InterruptedException ie) {}
            }
        }
        throw new NoSuchElementException("Element not found after " + MAX_RETRIES + " attempts: " + locator);
    }

    public void waitForPageToLoad(WebDriver driver) {
        new WebDriverWait(driver, Duration.ofSeconds(30)).until(d -> {
            String readyState = ((JavascriptExecutor) d)
                .executeScript("return document.readyState").toString();
            return "complete".equals(readyState);
        });

        // Wait for jQuery if present
        new WebDriverWait(driver, Duration.ofSeconds(10)).until(d -> {
            Boolean jQueryLoaded = (Boolean) ((JavascriptExecutor) d)
                .executeScript("return window.jQuery !== undefined");
            if (!jQueryLoaded) return true;
            Long ajaxCalls = (Long) ((JavascriptExecutor) d)
                .executeScript("return window.jQuery.active");
            return ajaxCalls == 0;
        });
    }
}

