public class LoginPage extends BasePage {

    // Page elements with custom timeout
    @FindBy(id = "username")
    @CacheLookup
    private WebElement usernameField;

    @FindBy(id = "password")
    private WebElement passwordField;

    @FindBy(css = "button[type='submit']")
    private WebElement loginButton;

    @FindBy(className = "error-message")
    private WebElement errorMessage;

    public LoginPage(WebDriver driver) {
        super(driver);
    }

    @Override
    protected void load() {
        driver.get("https://app.example.com/login");
        wait.until(ExpectedConditions.urlContains("login"));
    }

    @Override
    protected void isLoaded() throws Error {
        Assert.assertTrue(driver.getCurrentUrl().contains("login"), "Not on login page");
        Assert.assertTrue(usernameField.isDisplayed(), "Username field not displayed");
        Assert.assertTrue(passwordField.isDisplayed(), "Password field not displayed");
    }

    // Fluent interface methods
    public LoginPage enterUsername(String username) {
        wait.until(ExpectedConditions.elementToBeClickable(usernameField));
        usernameField.clear();
        usernameField.sendKeys(username);
        return this;
    }

    public LoginPage enterPassword(String password) {
        wait.until(ExpectedConditions.elementToBeClickable(passwordField));
        passwordField.clear();
        passwordField.sendKeys(password);
        return this;
    }

    public HomePage clickLogin() {
        wait.until(ExpectedConditions.elementToBeClickable(loginButton));
        loginButton.click();
        return new HomePage(driver).get();
    }

    public LoginPage clickLoginExpectingError() {
        wait.until(ExpectedConditions.elementToBeClickable(loginButton));
        loginButton.click();
        wait.until(ExpectedConditions.visibilityOf(errorMessage));
        return this;
    }

    public String getErrorMessage() {
        return errorMessage.getText();
    }

    // Business logic method
    public HomePage loginAs(String username, String password) {
        return enterUsername(username)
               .enterPassword(password)
               .clickLogin();
    }
}

