// DriverFactory Implementation
public class DriverFactory {

    private static final ThreadLocal<WebDriver> driverThreadLocal = new ThreadLocal<>();

    public static WebDriver createDriver(Browser browser, boolean isHeadless) {
        WebDriver driver;

        switch (browser) {
            case CHROME:
                driver = createChromeDriver(isHeadless);
                break;
            case FIREFOX:
                driver = createFirefoxDriver(isHeadless);
                break;
            case EDGE:
                driver = createEdgeDriver();
                break;
            case SAFARI:
                driver = createSafariDriver();
                break;
            case REMOTE:
                driver = createRemoteDriver();
                break;
            default:
                throw new IllegalArgumentException("Unsupported browser: " + browser);
        }

        // Common configurations
        driver.manage().window().maximize();
        driver.manage().timeouts().pageLoadTimeout(Duration.ofSeconds(30));
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(0)); // Disable implicit wait

        // Register event listeners
        WebDriver augmentedDriver = new EventFiringDecorator(new WebDriverListenerImpl())
            .decorate(driver);

        driverThreadLocal.set(augmentedDriver);
        return augmentedDriver;
    }

    private static WebDriver createChromeDriver(boolean headless) {
        ChromeOptions options = new ChromeOptions();

        if (headless) {
            options.addArguments("--headless=new");
        }

        // Performance optimizations
        options.addArguments("--disable-gpu");
        options.addArguments("--no-sandbox");
        options.addArguments("--disable-dev-shm-usage");
        options.addArguments("--window-size=1920,1080");

        // Disable automation flags detection
        options.setExperimentalOption("excludeSwitches", 
            Arrays.asList("enable-automation"));
        options.setExperimentalOption("useAutomationExtension", false);

        // Download preferences
        Map<String, Object> prefs = new HashMap<>();
        prefs.put("download.default_directory", 
            System.getProperty("user.dir") + File.separator + "downloads");
        prefs.put("download.prompt_for_download", false);
        prefs.put("plugins.always_open_pdf_externally", true);
        options.setExperimentalOption("prefs", prefs);

        // Chrome DevTools Protocol capabilities
        options.setCapability("goog:loggingPrefs", 
            Collections.singletonMap("performance", "ALL"));

        return new ChromeDriver(options);
    }

    private static WebDriver createRemoteDriver() {
        DesiredCapabilities capabilities = new DesiredCapabilities();
        capabilities.setBrowserName("chrome");
        capabilities.setPlatform(Platform.ANY);

        // Add custom capabilities
        capabilities.setCapability("selenoid:options", Map.of(
            "enableVNC", true,
            "enableVideo", true,
            "videoName", "test_execution.mp4",
            "videoScreenSize", "1920x1080",
            "timeZone", "America/New_York"
        ));

        try {
            return new RemoteWebDriver(
                new URL("http://localhost:4444/wd/hub"), 
                capabilities
            );
        } catch (MalformedURLException e) {
            throw new RuntimeException("Invalid grid URL", e);
        }
    }

    public static WebDriver getDriver() {
        return driverThreadLocal.get();
    }

    public static void quitDriver() {
        WebDriver driver = driverThreadLocal.get();
        if (driver != null) {
            try {
                driver.quit();
            } catch (Exception e) {
                logger.error("Error quitting driver", e);
            }
            driverThreadLocal.remove();
        }
    }
}

public interface TestDataProvider<T> {
    List<T> getTestData(String dataSetName);
    T getSingleTestData(String dataSetName);
    void saveTestData(String dataSetName, T data);
}

public class ExcelTestDataProvider implements TestDataProvider<User> {
    private static final String DATA_FILE_PATH = "src/test/resources/testdata/users.xlsx";

    @Override
    public List<User> getTestData(String sheetName) {
        List<User> users = new ArrayList<>();
        try (FileInputStream fis = new FileInputStream(DATA_FILE_PATH)) {
            Workbook workbook = new XSSFWorkbook(fis);
            Sheet sheet = workbook.getSheet(sheetName);

            // Skip header row
            for (int i = 1; i <= sheet.getLastRowNum(); i++) {
                Row row = sheet.getRow(i);
                if (row != null) {
                    User user = new User.Builder()
                        .withUsername(getCellValue(row.getCell(0)))
                        .withPassword(getCellValue(row.getCell(1)))
                        .withEmail(getCellValue(row.getCell(2)))
                        .withRole(getCellValue(row.getCell(3)))
                        .withActive(Boolean.parseBoolean(getCellValue(row.getCell(4))))
                        .build();
                    users.add(user);
                }
            }
            workbook.close();
        } catch (IOException e) {
            throw new FrameworkException("Error reading test data from Excel", e);
        }
        return users;
    }

    @Override
    public User getSingleTestData(String sheetName) {
        List<User> users = getTestData(sheetName);
        return users.isEmpty() ? null : users.get(0);
    }

    private String getCellValue(Cell cell) {
        if (cell == null) return "";

        switch (cell.getCellType()) {
            case STRING: return cell.getStringCellValue();
            case NUMERIC: 
                if (DateUtil.isCellDateFormatted(cell)) {
                    return cell.getDateCellValue().toString();
                } else {
                    return String.valueOf((int) cell.getNumericCellValue());
                }
            case BOOLEAN: return String.valueOf(cell.getBooleanCellValue());
            case FORMULA: return cell.getCellFormula();
            default: return "";
        }
    }
}

public class User {
    private String username;
    private String password;
    private String email;
    private String role;
    private boolean active;

    // Builder pattern for complex object creation
    public static class Builder {
        private String username;
        private String password;
        private String email;
        private String role;
        private boolean active;

        public Builder withUsername(String username) {
            this.username = username;
            return this;
        }

        public Builder withPassword(String password) {
            this.password = password;
            return this;
        }

        public Builder withEmail(String email) {
            this.email = email;
            return this;
        }

        public Builder withRole(String role) {
            this.role = role;
            return this;
        }

        public Builder withActive(boolean active) {
            this.active = active;
            return this;
        }

        public User build() {
            return new User(this);
        }
    }

    private User(Builder builder) {
        this.username = builder.username;
        this.password = builder.password;
        this.email = builder.email;
        this.role = builder.role;
        this.active = builder.active;
    }

    // Getters and other methods
}

public class TestDataFactory {

    private static final Map<String, TestDataProvider<?>> providers = new HashMap<>();

    static {
        providers.put("excel", new ExcelTestDataProvider());
        providers.put("json", new JsonTestDataProvider());
        providers.put("database", new DatabaseTestDataProvider());
    }

    public static <T> List<T> getTestData(String source, String dataSetName, Class<T> type) {
        TestDataProvider<T> provider = (TestDataProvider<T>) providers.get(source);
        if (provider == null) {
            throw new IllegalArgumentException("Unsupported data source: " + source);
        }
        return provider.getTestData(dataSetName);
    }

    public static User generateRandomUser() {
        Faker faker = new Faker();
        return new User.Builder()
            .withUsername(faker.name().username())
            .withPassword(faker.internet().password(8, 12, true, true, true))
            .withEmail(faker.internet().emailAddress())
            .withRole(faker.options().option("admin", "user", "manager"))
            .withActive(faker.bool().bool())
            .build();
    }
}

