pipeline {
    agent {
        docker {
            image 'maven:3.8.4-openjdk-11'
            args '-v /var/run/docker.sock:/var/run/docker.sock'
        }
    }

    environment {
        // Configuration
        ENVIRONMENT = 'staging'
        BROWSER = 'chrome'
        HEADLESS = 'true'
        PARALLEL_THREADS = '4'

        // URLs
        APP_URL = 'https://staging.example.com'
        API_URL = 'https://api.staging.example.com'

        // Cloud services
        BROWSERSTACK_USER = credentials('browserstack-user')
        BROWSERSTACK_KEY = credentials('browserstack-key')

        // Reporting
        ALLURE_RESULTS = 'target/allure-results'
        EXTENT_REPORT = 'target/extent-report'
    }

    options {
        buildDiscarder(logRotator(numToKeepStr: '10'))
        timeout(time: 2, unit: 'HOURS')
        disableConcurrentBuilds()
    }

    stages {
        stage('Checkout & Setup') {
            steps {
                checkout scm
                sh 'git version'
                sh 'mvn --version'
                sh 'java -version'
            }
        }

        stage('Dependency Installation') {
            steps {
                sh 'mvn clean compile -DskipTests'
            }
        }

        stage('Code Quality Check') {
            steps {
                sh '''
                mvn checkstyle:check
                mvn pmd:check
                mvn spotbugs:check
                mvn jacoco:prepare-agent test jacoco:report
                '''
            }
            post {
                success {
                    publishHTML(target: [
                        reportDir: 'target/site/jacoco',
                        reportFiles: 'index.html',
                        reportName: 'Code Coverage Report'
                    ])
                }
            }
        }

        stage('Unit Tests') {
            steps {
                sh 'mvn test -Dtest=*UnitTest -DfailIfNoTests=false'
            }
            post {
                always {
                    junit 'target/surefire-reports/*.xml'
                    archiveArtifacts 'target/surefire-reports/*.xml'
                }
            }
        }

        stage('API Integration Tests') {
            steps {
                sh '''
                mvn test -Dtest=*ApiTest \
                    -Dapi.base.url=${API_URL} \
                    -Denvironment=${ENVIRONMENT}
                '''
            }
            post {
                always {
                    junit 'target/surefire-reports/*.xml'
                }
            }
        }

        stage('UI Smoke Tests') {
            steps {
                sh '''
                mvn test -Dtest=SmokeTest \
                    -Dbrowser=${BROWSER} \
                    -Dheadless=${HEADLESS} \
                    -Dapp.url=${APP_URL} \
                    -Dthread.count=2 \
                    -Denvironment=${ENVIRONMENT}
                '''
            }
            post {
                always {
                    junit 'target/surefire-reports/*.xml'
                    archiveArtifacts 'target/screenshots/*.png'
                }
            }
        }

        stage('UI Regression Tests (Parallel)') {
            when {
                expression { params.RUN_REGRESSION }
            }
            steps {
                script {
                    def stages = [:]
                    def browsers = ['chrome', 'firefox', 'edge']

                    browsers.each { browser ->
                        stages["UI Tests - ${browser}"] = {
                            sh '''
                            mvn test -Dtest=RegressionTest \
                                -Dbrowser=${browser} \
                                -Dheadless=true \
                                -Dapp.url=${APP_URL} \
                                -Dthread.count=${PARALLEL_THREADS} \
                                -Denvironment=${ENVIRONMENT}
                            '''
                        }
                    }

                    parallel stages
                }
            }
            post {
                always {
                    junit 'target/surefire-reports/*.xml'
                    archiveArtifacts 'target/screenshots/*.png'
                    archiveArtifacts 'target/videos/*.mp4'
                }
            }
        }

        stage('Cross-Browser Cloud Tests') {
            when {
                expression { params.RUN_CLOUD_TESTS }
            }
            steps {
                sh '''
                mvn test -Dtest=CrossBrowserTest \
                    -Dremote.url=https://${BROWSERSTACK_USER}:${BROWSERSTACK_KEY}@hub-cloud.browserstack.com/wd/hub \
                    -Dapp.url=${APP_URL} \
                    -Dcloud.platform=BROWSERSTACK \
                    -Denvironment=${ENVIRONMENT}
                '''
            }
        }

        stage('Performance Tests') {
            when {
                expression { params.RUN_PERFORMANCE_TESTS }
            }
            steps {
                sh '''
                mvn gatling:test -Dgatling.simulationClass=LoadSimulation \
                    -Dapi.base.url=${API_URL}
                '''
            }
            post {
                always {
                    archiveArtifacts 'target/gatling/**/*'
                    publishHTML(target: [
                        reportDir: 'target/gatling/latest',
                        reportFiles: 'index.html',
                        reportName: 'Performance Test Report'
                    ])
                }
            }
        }

        stage('Security Scan') {
            when {
                expression { params.RUN_SECURITY_SCAN }
            }
            steps {
                sh 'mvn org.owasp:dependency-check-maven:check'
                sh 'mvn org.sonarsource.scanner.maven:sonar-maven-plugin:sonar'
            }
            post {
                always {
                    dependencyCheckPublisher(pattern: 'target/dependency-check-report.xml')
                }
            }
        }

        stage('Generate Reports') {
            steps {
                sh '''
                # Generate Allure report
                allure generate ${ALLURE_RESULTS} -o target/allure-report --clean

                # Generate Extent report
                mvn exec:java -Dexec.mainClass="com.example.ReportGenerator"

                # Generate custom dashboard
                python scripts/generate_dashboard.py
                '''
            }
            post {
                always {
                    publishHTML(target: [
                        reportDir: 'target/allure-report',
                        reportFiles: 'index.html',
                        reportName: 'Allure Test Report'
                    ])
                    publishHTML(target: [
                        reportDir: 'target/extent-report',
                        reportFiles: 'index.html',
                        reportName: 'Extent Test Report'
                    ])
                    archiveArtifacts 'target/reports/**/*'
                }
            }
        }

        stage('Quality Gates') {
            steps {
                script {
                    // Check test results
                    def testResults = readJSON file: 'target/test-results.json'

                    if (testResults.successRate < 95) {
                        error "Quality gate failed: Test success rate ${testResults.successRate}% < 95%"
                    }

                    if (testResults.criticalFailures > 0) {
                        error "Quality gate failed: ${testResults.criticalFailures} critical test failures"
                    }

                    // Check code coverage
                    def coverage = readFile 'target/site/jacoco/jacoco.xml'
                    def matcher = coverage =~ /<counter type="LINE" missed="(\d+)" covered="(\d+)"\/>/
                    if (matcher.find()) {
                        def missed = matcher.group(1).toInteger()
                        def covered = matcher.group(2).toInteger()
                        def lineCoverage = covered / (missed + covered) * 100

                        if (lineCoverage < 80) {
                            error "Quality gate failed: Line coverage ${lineCoverage}% < 80%"
                        }
                    }

                    echo "All quality gates passed!"
                }
            }
        }
    }

    post {
        always {
            // Cleanup
            sh 'docker system prune -f'

            // Update test dashboard
            sh 'python scripts/update_dashboard.py'

            // Archive artifacts
            archiveArtifacts 'target/**/*.zip'
        }

        success {
            // Success notifications
            slackSend(
                channel: '#build-success',
                color: 'good',
                message: "✅ Build ${env.JOB_NAME} #${env.BUILD_NUMBER} succeeded!\nTest Results: ${env.BUILD_URL}testReport"
            )

            emailext(
                to: 'qa-team@example.com',
                subject: "✅ Test Automation Success: ${env.JOB_NAME} #${env.BUILD_NUMBER}",
                body: "Build succeeded!\n\nReport: ${env.BUILD_URL}allure"
            )
        }

        failure {
            // Failure notifications
            slackSend(
                channel: '#build-failures',
                color: 'danger',
                message: "🚨 Build ${env.JOB_NAME} #${env.BUILD_NUMBER} failed!\nLogs: ${env.BUILD_URL}console"
            )

            emailext(
                to: 'qa-team@example.com; dev-team@example.com',
                subject: "🚨 Test Automation Failure: ${env.JOB_NAME} #${env.BUILD_NUMBER}",
                body: "Build failed!\n\nLogs: ${env.BUILD_URL}console\n\nPlease investigate immediately."
            )

            // Attach failure logs
            archiveArtifacts 'target/logs/*.log'

            // Create JIRA ticket for test failures
            script {
                def testFailures = sh(script: 'grep -r "FAILED" target/surefire-reports/*.xml | wc -l', returnStdout: true).trim()
                if (testFailures.toInteger() > 0) {
                    withCredentials([usernamePassword(credentialsId: 'jira-credentials', 
                        usernameVariable: 'JIRA_USER', passwordVariable: 'JIRA_PASS')]) {
                        sh '''
                        curl -u ${JIRA_USER}:${JIRA_PASS} -X POST \
                            -H "Content-Type: application/json" \
                            -d '{
                                "fields": {
                                    "project": {"key": "QA"},
                                    "summary": "Test Automation Failure in Build ${env.BUILD_NUMBER}",
                                    "description": "${env.JOB_NAME} build #${env.BUILD_NUMBER} failed with test failures.\n\nBuild URL: ${env.BUILD_URL}\n\nPlease investigate the test failures.",
                                    "issuetype": {"name": "Bug"},
                                    "priority": {"name": "High"}
                                }
                            }' \
                            https://jira.example.com/rest/api/2/issue/
                        '''
                    }
                }
            }
        }

        unstable {
            // Unstable build notifications
            slackSend(
                channel: '#build-warnings',
                color: 'warning',
                message: "⚠️ Build ${env.JOB_NAME} #${env.BUILD_NUMBER} is unstable\nReport: ${env.BUILD_URL}testReport"
            )
        }
    }
}

