    async def automate_permission_flow(self, permission_type: str, 
                                     action: str = 'grant', 
                                     context: Dict[str, Any] = None) -> Dict[str, Any]:
        """
        Automate permission request and response flow.
        """

        result = {
            'permission_type': permission_type,
            'action': action,
            'steps': [],
            'success': False
        }

        try:
            # Step 1: Trigger permission request
            result['steps'].append({
                'action': 'trigger_permission_request',
                'timestamp': time.time()
            })

            await self._trigger_permission_request(permission_type)

            # Step 2: Detect permission dialog
            result['steps'].append({
                'action': 'detect_permission_dialog',
                'timestamp': time.time()
            })

            dialog_detected = await self.permission_automator.detect_permission_dialog(
                permission_type
            )

            if not dialog_detected:
                # Check if permission was already granted/denied
                current_state = await self.permission_automator.get_permission_state(permission_type)
                result['current_state'] = current_state
                result['success'] = True
                return result

            # Step 3: Respond to permission dialog
            result['steps'].append({
                'action': 'respond_to_dialog',
                'timestamp': time.time()
            })

            response_result = await self.permission_automator.respond_to_permission_dialog(
                permission_type, action, context
            )

            result['steps'].extend(response_result['steps'])

            # Step 4: Verify permission state
            result['steps'].append({
                'action': 'verify_permission_state',
                'timestamp': time.time()
            })

            verified_state = await self.permission_automator.verify_permission_state(
                permission_type, action
            )

            result['success'] = verified_state
            result['verified_state'] = verified_state
            result['metrics'] = {
                'dialog_detection_time': response_result.get('detection_time', 0),
                'response_time': response_result.get('response_time', 0),
                'total_time': time.time() - result['steps'][0]['timestamp']
            }

        except Exception as e:
            result['error'] = str(e)
            result['steps'].append({
                'action': 'error',
                'error': str(e),
                'timestamp': time.time()
            })

        return result

    async def test_deep_link_scenario(self, deep_link: str, 
