class NotificationHandler:
    """
    Handler for push notification testing across platforms.
    """

    def __init__(self, platform: str):
        self.platform = platform
        self.fcm_client = FCMClient() if platform == 'android' else None
        self.apns_client = APNSClient() if platform == 'ios' else None
        self.notification_detector = NotificationDetector(platform)

    async def send_push_notification(self, payload: Dict[str, Any]) -> str:
        """Send push notification to device."""

        if self.platform == 'android':
            return await self.fcm_client.send_test_notification(payload)
        elif self.platform == 'ios':
            return await self.apns_client.send_test_notification(payload)
        else:
            raise ValueError(f"Unsupported platform: {self.platform}")

    async def wait_for_notification_delivery(self, notification_id: str, 
                                           timeout: int = 30) -> bool:
        """Wait for notification to appear on device."""

        start_time = time.time()
        while time.time() - start_time < timeout:
            if await self.notification_detector.is_notification_present(notification_id):
                return True
            await asyncio.sleep(1)

        return False

    async def interact_with_notification(self, notification_id: str, 
                                       interaction_type: str) -> Dict[str, Any]:
        """Interact with notification (tap, dismiss, etc.)"""

        result = {
            'steps': [],
            'success': False
        }

        # Find notification on screen
        notification_element = await self.notification_detector.find_notification_element(
            notification_id
        )

        if not notification_element:
            result['error'] = "Notification not found on screen"
            return result

        # Perform interaction based on type
        if interaction_type == 'tap':
            interaction_result = await self._tap_notification(notification_element)
        elif interaction_type == 'dismiss':
            interaction_result = await self._dismiss_notification(notification_element)
        elif interaction_type == 'action_button':
            interaction_result = await self._tap_action_button(notification_element)
        else:
            raise ValueError(f"Unknown interaction type: {interaction_type}")

        result.update(interaction_result)
        return result

